def kth_missing_brute(a: list[int], k: int) -> int:
    for v in a:
        if v <= k:
            k += 1
        else:
            break
    return k

def kth_missing(a: list[int], k: int) -> int:
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        missing = a[mid] - (mid + 1)
        if missing < k:
            lo = mid + 1
        else:
            hi = mid - 1
    return lo + k
